-- Park and Shop
UPDATE projects SET seoKeywords = 'scenic design, Park and Shop, musical theatre, New Swan Theatre, retail comedy' WHERE slug = 'park-and-shop';

INSERT IGNORE INTO tags (name) VALUES ('Musical Theatre'), ('Retail'), ('1950s America');

INSERT IGNORE INTO projectTags (projectId, tagId)
SELECT p.id, t.id FROM projects p, tags t 
WHERE p.slug = 'park-and-shop' AND t.name IN ('Musical Theatre', 'Retail', '1950s America', 'Theatre Festival', '2024');

